example_item.example_item_data:
if nelson.io.zstd.isavailable()
  text = repmat('Zstandard ', 1, 100);
  packed = nelson.io.zstd.compress(text, 'Level', 9);
  [numel(text), numel(packed)]
  isequal(nelson.io.zstd.decompresstext(packed), text)
end

if nelson.io.zstd.isavailable()
  source = [tempdir(), 'zstd_example.txt'];
  filewrite(source, repmat(sprintf('line\n'), 1, 1000));
  packed = nelson.io.zstd.compressfile(source)
  restored = nelson.io.zstd.decompressfile(packed, [tempdir(), 'zstd_example_restored.txt'])
end

if nelson.io.zstd.isavailable()
  fid = nelson.io.zstd.fopen([], 'w');
  fprintf(fid, 'line %d\n', 1:3);
  bytes = nelson.io.zstd.tobytes(fid);
  fid = nelson.io.zstd.fopen(bytes);
  first = fgetl(fid)
  rest = fread(fid, '*char')'
  fclose(fid);
end

if nelson.io.zstd.isavailable()
  filename = [tempname(), '.zst'];
  fid = nelson.io.zstd.fopen(filename, 'w');
  fprintf(fid, 'first frame
');
  fclose(fid);
  fid = nelson.io.zstd.fopen(filename, 'a');
  fprintf(fid, 'second frame
');
  fclose(fid);
  fid = nelson.io.zstd.fopen(filename);
  txt = fread(fid, '*char')'
  fclose(fid);
  delete(filename);
  data = uint8(mod(1:3000000, 251));
  fid = nelson.io.zstd.fopen(filename, 'w', 'Seekable', true, 'Workers', 'auto');
  fwrite(fid, data);
  fclose(fid);
  fid = nelson.io.zstd.fopen(filename);
  fseek(fid, 2500000, 'bof');
  value = fread(fid, 4, 'uint8=>uint8')'
  fclose(fid);
  delete(filename);
end
